export async function readCatalog(url, { fetchImpl = fetch, signal } = {}) {
  const response = await fetchImpl(url, { method: 'GET', signal });
  return { status: response.status, ok: response.ok, data: await response.json() };
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { readCatalog } from '../src/catalog-client.mjs';

test('client retains status and forwards cancellation without real network', async () => {
  const controller = new AbortController();
  let request;
  const result = await readCatalog('https://supplier.invalid/products', {
    signal: controller.signal,
    fetchImpl: async (url, options) => { request = { url, options }; return new Response(JSON.stringify({ issue: 'busy' }), { status: 503 }); },
  });
  assert.deepEqual(result, { status: 503, ok: false, data: { issue: 'busy' } });
  assert.equal(request.options.method, 'GET');
  assert.equal(request.options.signal, controller.signal);
});
